sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  // The list of locations, managers, and subjects passed from the server-side script
  $scope.locations = c.data.locations;
  $scope.managers = c.data.managers;
  $scope.subjects = c.data.subjects;
};

sp_widget.script:
(function() {
  var locationList = [];
  var managerSet = new Set();  // Use Set to ensure unique managers
  var subjectList = [];  // For storing the labels of the subject field

  // Query for Locations
  var locationGR = new GlideRecord('cmn_location');
  locationGR.query();
  while (locationGR.next()) {
    locationList.push(locationGR.name.toString());
  }
  // Sort locationList alphabetically
  locationList.sort();

  // Query for Managers (with specified roles)
  var roleId = ['ce3ae88383bb12100c1eb3a6feaad38a', 'ce3ae88383bb12100c1eb3a6feaad390'];
  var roleGR = new GlideRecord('sys_user_has_role');
  roleGR.addQuery('role', 'IN', roleId.join(','));
  roleGR.query();
  while (roleGR.next()) {
    var managerName = roleGR.user.name;
    managerSet.add(managerName.toString());
  }
  // Convert the Set to an array and sort alphabetically
  var managerList = Array.from(managerSet);
  managerList.sort();

  // Query sys_choice for the 'subject' field in the custom table 'x_1297629_confer_0_conferences'
  var choiceGR = new GlideRecord('sys_choice');
  choiceGR.addQuery('name', 'x_1297629_confer_0_conferences');  // Custom table
  choiceGR.addQuery('element', 'subject');  // Field name in the custom table (must match exactly)
  choiceGR.query();

  // Loop through the results to get the labels for the subject choices
  while (choiceGR.next()) {
    subjectList.push(choiceGR.label.toString());  // Add the label (choice) to the list
  }
  // Sort subjects alphabetically
  subjectList.sort();

  // Pass the collected data to the client-side script
  data.locations = locationList;
  data.managers = managerList;  // Send sorted, unique manager names to the client-side
  data.subjects = subjectList;  // Send sorted subjects to the client-side
})();
